# ───────────────────────── 기물 도우미 ─────────────────────────
def P(id, cw, ch, kind, name, text, pri=3, **kw):
    cls = 'flat' if kind == 'flat' else 'wallm' if kind == 'wall_mounted' else 'prop'
    U(id, cw * 16 // (2 if kw.get('mirror') else 1), ch * 16, cls, kind, name, text, pri=pri, **kw)


def B(id, cw, ch, roof, name, text, **kw):
    """한 번에 그리는 건물(좌우 대칭 반쪽). roof = 지붕 줄 수."""
    U(id, cw * 8, ch * 16, 'bwhole', 'building', name + ' (left half)', text, pri=1, mirror=True, roof=roof, door=kw.pop('door', True), **kw)


