# ───────────────────────── 네온 거리: 건물 (pri 1) ─────────────────────────
def TOWER(id, half_w, roof_h, mid_h, ground_h, name, roof_text, mid_text, ground_text):
    U(f'{id}.roof', half_w, roof_h, 'roof', 'roof', f'{name}: ROOF piece (left half)', roof_text, pri=1, mirror=True)
    U(f'{id}.mid', half_w, mid_h, 'mid', 'mid', f'{name}: MIDDLE STOREYS piece (left half)', mid_text, pri=1, mirror=True, needs=f'{id}.roof')
    U(f'{id}.wall', half_w, ground_h, 'wall', 'wall', f'{name}: GROUND FLOOR piece (left half)', ground_text, pri=1, mirror=True, needs=f'{id}.mid', door=True,
      needs_head='MIDDLE STOREYS PIECE (already drawn; it sits directly above your canvas: its last row touches your row 0; keep its wall colours and its vertical lines)')


